steps.script:
# Ignore the suggestion: begin a normal move on a unit the AI did NOT pick.
var sug: Dictionary = AIPlayer.request_suggestion()
var picked := str(sug.get("actor_unit_id", ""))
var uid := ""
for a in PhaseManager.get_available_actions():
	if str(a.get("type", "")) == "BEGIN_NORMAL_MOVE":
		var u := str(a.get("actor_unit_id", ""))
		if uid == "" or u != picked:
			uid = u
			if u != picked:
				break
var r = PhaseManager.current_phase_instance.execute_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": uid})
return r.get("success", false)

for a in PhaseManager.get_available_actions():
	if str(a.get("type", "")) == "CONFIRM_UNIT_MOVE":
		return true
return false
